static const uint8_t mlkem1024_ss[32] = {
	0x5d, 0x13, 0x50, 0xc0, 0x93, 0x7b, 0x62, 0x22, 0x66, 0x2f, 0x3d, 0x0a,
	0x61, 0x94, 0xb8, 0xf1, 0xb6, 0x0d, 0x4a, 0xea, 0xf9, 0x4f, 0xb8, 0x42,
	0x6c, 0x91, 0x07, 0x8b, 0x6c, 0x12, 0x04, 0x1d,
};

/* ML-DSA signature-verification KAT: the stored (pub, msg, sig) must verify,
 * and a corrupted signature must be rejected.  No key generation, no RNG. */
static int test_ml_dsa_kat(gnutls_pk_algorithm_t algo, const uint8_t *pub,
			   size_t pub_size, const uint8_t *msg, size_t msg_size,
			   const uint8_t *sig, size_t sig_size)
{
	int ret;
	gnutls_pk_params_st params;
	gnutls_x509_spki_st spki;
	gnutls_datum_t vdata = { .data = (void *)msg, .size = msg_size };
	gnutls_datum_t vsig = { .data = (void *)sig, .size = sig_size };
	uint8_t *bad = NULL;

	memset(&spki, 0, sizeof(spki));
	gnutls_pk_params_init(&params);
	params.algo = algo;
	/* raw_pub aliases a static const vector and is never freed, so this
	 * function must not call gnutls_pk_params_release(). */
	params.raw_pub.data = (void *)pub;
	params.raw_pub.size = pub_size;

	/* Positive KAT: the stored signature must verify. */
	ret = _gnutls_pk_verify(algo, &vdata, &vsig, &params, &spki);
	if (ret < 0) {
		gnutls_assert();
		goto cleanup;
	}

	/* Negative KAT: a corrupted signature must fail to verify. */
	bad = gnutls_malloc(sig_size);
	if (bad == NULL) {
		ret = gnutls_assert_val(GNUTLS_E_MEMORY_ERROR);
		goto cleanup;
	}
	memcpy(bad, sig, sig_size);
	bad[0] ^= 0x01;
	vsig.data = bad;

	ret = _gnutls_pk_verify(algo, &vdata, &vsig, &params, &spki);
	if (ret != GNUTLS_E_PK_SIG_VERIFY_FAILED) {
		ret = gnutls_assert_val(GNUTLS_E_SELF_TEST_ERROR);
		goto cleanup;
	}

	ret = 0;
cleanup:
	gnutls_free(bad);
	_gnutls_debug_log("%s KAT %s\n", gnutls_pk_get_name(algo),
			  (ret < 0) ? "failed" : "succeeded");
	return ret;
}

/* ML-KEM decapsulation KAT: decapsulating the stored ciphertext with the
 * stored decapsulation key must yield the stored shared secret. */
static int test_ml_kem_kat(gnutls_pk_algorithm_t algo, const uint8_t *dk,
			   size_t dk_size, const uint8_t *ct, size_t ct_size,
			   const uint8_t *k, size_t k_size)
{
	int ret;
	gnutls_datum_t priv = { .data = (void *)dk, .size = dk_size };
	gnutls_datum_t ctd = { .data = (void *)ct, .size = ct_size };
	gnutls_datum_t ss = { NULL, 0 };

	ret = _gnutls_pk_decaps(algo, &ss, &ctd, &priv);
	if (ret < 0) {
		gnutls_assert();
		goto cleanup;
	}

	if (ss.size != k_size || memcmp(ss.data, k, k_size) != 0) {
		ret = gnutls_assert_val(GNUTLS_E_SELF_TEST_ERROR);
		goto cleanup;
	}

	ret = 0;
cleanup:
	_gnutls_free_key_datum(&ss);
	_gnutls_debug_log("%s KAT %s\n", gnutls_pk_get_name(algo),
			  (ret < 0) ? "failed" : "succeeded");
	return ret;
}
#endif /* HAVE_LEANCRYPTO */

/*-
 * gnutls_pk_self_test:
 * @flags: GNUTLS_SELF_TEST_FLAG flags
 * @pk: the algorithm to use
 *
 * This function will run self tests on the provided public key algorithm.
 *
 * Returns: Zero or a negative error code on error.
 *
 * Since: 3.3.0-FIPS140
 -*/
int gnutls_pk_self_test(unsigned flags, gnutls_pk_algorithm_t pk)
{
	int ret;

	bool is_post = false;
	bool is_fips140_mode_enabled = false;

	if (flags & GNUTLS_SELF_TEST_FLAG_ALL)
		pk = GNUTLS_PK_UNKNOWN;

	if (_gnutls_get_lib_state() == LIB_STATE_SELFTEST)
		is_post = true;

	if (gnutls_fips140_mode_enabled())
		is_fips140_mode_enabled = true;

	switch (pk) {
	case GNUTLS_PK_UNKNOWN:
		FALLTHROUGH;
	case GNUTLS_PK_DH:
		ret = test_dh();
		if (ret < 0) {
			gnutls_assert();
			goto cleanup;
		}

		if (!(flags & GNUTLS_SELF_TEST_FLAG_ALL))
			return 0;
		FALLTHROUGH;
	case GNUTLS_PK_RSA:
		PK_KNOWN_TEST(GNUTLS_PK_RSA, 2048, GNUTLS_DIG_SHA256,
			      rsa_2048_privkey, rsa_2048_sig, 0);

		PK_TEST(GNUTLS_PK_RSA, test_rsa_enc, 2048, 0);

		if (!(flags & GNUTLS_SELF_TEST_FLAG_ALL))
			return 0;

		FALLTHROUGH;
	case GNUTLS_PK_RSA_PSS:
		/* In POST, we switch the RNG to deterministic one so
		 * the KAT for RSA-PSS work. */
		if (is_post) {
			PK_KNOWN_TEST(GNUTLS_PK_RSA_PSS, 2048,
				      GNUTLS_DIG_SHA256, rsa_2048_privkey,
				      rsa_pss_2048_sig,
				      GNUTLS_PRIVKEY_SIGN_FLAG_RSA_PSS);
		} else {
			PK_TEST(GNUTLS_PK_RSA_PSS, test_sig, 2048,
				GNUTLS_SIGN_RSA_PSS_RSAE_SHA256);
		}

		if (!(flags & GNUTLS_SELF_TEST_FLAG_ALL))
			return 0;

		FALLTHROUGH;
	case GNUTLS_PK_RSA_OAEP:
		PK_TEST(GNUTLS_PK_RSA_OAEP, test_rsa_enc, 2048,
			GNUTLS_DIG_SHA256);

		if (!(flags & GNUTLS_SELF_TEST_FLAG_ALL))
			return 0;

		FALLTHROUGH;
#ifdef ENABLE_DSA
	case GNUTLS_PK_DSA:
		if (is_post || !is_fips140_mode_enabled) {
			PK_KNOWN_TEST(GNUTLS_PK_DSA, 2048, GNUTLS_DIG_SHA256,
				      dsa_2048_privkey, dsa_2048_sig,
				      GNUTLS_PRIVKEY_FLAG_REPRODUCIBLE);
		} else {
			PK_TEST(GNUTLS_PK_DSA, test_sig, 2048,
				GNUTLS_SIGN_DSA_SHA256);
		}

		if (!(flags & GNUTLS_SELF_TEST_FLAG_ALL))
			return 0;

		FALLTHROUGH;
#endif
	case GNUTLS_PK_EC:
		/* Test ECDH and ECDSA */
		ret = test_ecdh();
		if (ret < 0) {
			gnutls_assert();
			goto cleanup;
		}

		/* Test ECDSA */
		if (is_post || !is_fips140_mode_enabled) {
			PK_KNOWN_TEST(GNUTLS_PK_EC,
				      GNUTLS_CURVE_TO_BITS(
					      GNUTLS_ECC_CURVE_SECP256R1),
				      GNUTLS_DIG_SHA256,
				      ecdsa_secp256r1_privkey,
				      ecdsa_secp256r1_sig,
				      GNUTLS_PRIVKEY_FLAG_REPRODUCIBLE);
		} else {
			PK_TEST(GNUTLS_PK_EC, test_sig,
				GNUTLS_CURVE_TO_BITS(
					GNUTLS_ECC_CURVE_SECP256R1),
				GNUTLS_SIGN_ECDSA_SHA256);
		}

		if (!(flags & GNUTLS_SELF_TEST_FLAG_ALL))
			return 0;

		if (is_post || !is_fips140_mode_enabled) {
			PK_KNOWN_TEST(GNUTLS_PK_EC,
				      GNUTLS_CURVE_TO_BITS(
					      GNUTLS_ECC_CURVE_SECP384R1),
				      GNUTLS_DIG_SHA384,
				      ecdsa_secp384r1_privkey,
				      ecdsa_secp384r1_sig,
				      GNUTLS_PRIVKEY_FLAG_REPRODUCIBLE);
		} else {
			PK_TEST(GNUTLS_PK_EC, test_sig,
				GNUTLS_CURVE_TO_BITS(
					GNUTLS_ECC_CURVE_SECP384R1),
				GNUTLS_SIGN_ECDSA_SHA384);
		}

		if (is_post || !is_fips140_mode_enabled) {
			PK_KNOWN_TEST(GNUTLS_PK_EC,
				      GNUTLS_CURVE_TO_BITS(
					      GNUTLS_ECC_CURVE_SECP521R1),
				      GNUTLS_DIG_SHA512,
				      ecdsa_secp521r1_privkey,
				      ecdsa_secp521r1_sig,
				      GNUTLS_PRIVKEY_FLAG_REPRODUCIBLE);
		} else {
			PK_TEST(GNUTLS_PK_EC, test_sig,
				GNUTLS_CURVE_TO_BITS(
					GNUTLS_ECC_CURVE_SECP521R1),
				GNUTLS_SIGN_ECDSA_SHA512);
		}

#ifdef ENABLE_NON_SUITEB_CURVES
		if (is_post || !is_fips140_mode_enabled) {
			PK_KNOWN_TEST(GNUTLS_PK_EC,
				      GNUTLS_CURVE_TO_BITS(
					      GNUTLS_ECC_CURVE_SECP192R1),
				      GNUTLS_DIG_SHA256,
				      ecdsa_secp192r1_privkey,
				      ecdsa_secp192r1_sig,
				      GNUTLS_PRIVKEY_FLAG_REPRODUCIBLE);
		} else {
			PK_TEST(GNUTLS_PK_EC, test_sig,
				GNUTLS_CURVE_TO_BITS(
					GNUTLS_ECC_CURVE_SECP192R1),
				GNUTLS_SIGN_ECDSA_SHA256);
		}

		if (is_post || !is_fips140_mode_enabled) {
			PK_KNOWN_TEST(GNUTLS_PK_EC,
				      GNUTLS_CURVE_TO_BITS(
					      GNUTLS_ECC_CURVE_SECP224R1),
				      GNUTLS_DIG_SHA256,
				      ecdsa_secp224r1_privkey,
				      ecdsa_secp224r1_sig,
				      GNUTLS_PRIVKEY_FLAG_REPRODUCIBLE);
		} else {
			PK_TEST(GNUTLS_PK_EC, test_sig,
				GNUTLS_CURVE_TO_BITS(
					GNUTLS_ECC_CURVE_SECP224R1),
				GNUTLS_SIGN_ECDSA_SHA256);
		}
#endif

#if ENABLE_GOST
		FALLTHROUGH;
	case GNUTLS_PK_GOST_01:
		PK_TEST(GNUTLS_PK_GOST_01, test_sig,
			GNUTLS_CURVE_TO_BITS(GNUTLS_ECC_CURVE_GOST256CPA),
			GNUTLS_SIGN_GOST_94);

		if (!(flags & GNUTLS_SELF_TEST_FLAG_ALL))
			return 0;

		FALLTHROUGH;
	case GNUTLS_PK_GOST_12_256:
		PK_TEST(GNUTLS_PK_GOST_12_256, test_sig,
			GNUTLS_CURVE_TO_BITS(GNUTLS_ECC_CURVE_GOST256CPA),
			GNUTLS_SIGN_GOST_256);

		if (!(flags & GNUTLS_SELF_TEST_FLAG_ALL))
			return 0;

		FALLTHROUGH;
	case GNUTLS_PK_GOST_12_512:
		PK_TEST(GNUTLS_PK_GOST_12_512, test_sig,
			GNUTLS_CURVE_TO_BITS(GNUTLS_ECC_CURVE_GOST512A),
			GNUTLS_SIGN_GOST_512);

		if (!(flags & GNUTLS_SELF_TEST_FLAG_ALL))
			return 0;
#endif
		FALLTHROUGH;
	case GNUTLS_PK_EDDSA_ED25519:
		PK_KNOWN_TEST(GNUTLS_PK_EDDSA_ED25519,
			      GNUTLS_CURVE_TO_BITS(GNUTLS_ECC_CURVE_ED25519),
			      GNUTLS_DIG_SHA512, eddsa_ed25519_privkey,
			      eddsa_ed25519_sig, 0);

		if (!(flags & GNUTLS_SELF_TEST_FLAG_ALL))
			return 0;

		FALLTHROUGH;
	case GNUTLS_PK_EDDSA_ED448:
		PK_KNOWN_TEST(GNUTLS_PK_EDDSA_ED448,
			      GNUTLS_CURVE_TO_BITS(GNUTLS_ECC_CURVE_ED448),
			      GNUTLS_DIG_SHAKE_256, eddsa_ed448_privkey,
			      eddsa_ed448_sig, 0);

		if (!(flags & GNUTLS_SELF_TEST_FLAG_ALL))
			return 0;

#ifdef HAVE_LEANCRYPTO
		FALLTHROUGH;
	case GNUTLS_PK_MLDSA44:
		ret = test_ml_dsa_kat(GNUTLS_PK_MLDSA44,
				      mldsa44_pub, sizeof(mldsa44_pub),
				      mldsa44_msg, sizeof(mldsa44_msg),
				      mldsa44_sig, sizeof(mldsa44_sig));
		if (ret < 0) {
			gnutls_assert();
			goto cleanup;
		}

		if (!(flags & GNUTLS_SELF_TEST_FLAG_ALL))
			return 0;

		FALLTHROUGH;
	case GNUTLS_PK_MLDSA65:
		ret = test_ml_dsa_kat(GNUTLS_PK_MLDSA65,
				      mldsa65_pub, sizeof(mldsa65_pub),
				      mldsa65_msg, sizeof(mldsa65_msg),
				      mldsa65_sig, sizeof(mldsa65_sig));
		if (ret < 0) {
			gnutls_assert();
			goto cleanup;
		}

		if (!(flags & GNUTLS_SELF_TEST_FLAG_ALL))
			return 0;

		FALLTHROUGH;
	case GNUTLS_PK_MLDSA87:
		ret = test_ml_dsa_kat(GNUTLS_PK_MLDSA87,
				      mldsa87_pub, sizeof(mldsa87_pub),
				      mldsa87_msg, sizeof(mldsa87_msg),
				      mldsa87_sig, sizeof(mldsa87_sig));
		if (ret < 0) {
			gnutls_assert();
			goto cleanup;
		}

		if (!(flags & GNUTLS_SELF_TEST_FLAG_ALL))
			return 0;

		FALLTHROUGH;
	case GNUTLS_PK_MLKEM768:
		ret = test_ml_kem_kat(GNUTLS_PK_MLKEM768,
				      mlkem768_dk, sizeof(mlkem768_dk),
				      mlkem768_ct, sizeof(mlkem768_ct),
				      mlkem768_ss, sizeof(mlkem768_ss));
		if (ret < 0) {
			gnutls_assert();
			goto cleanup;
		}

		if (!(flags & GNUTLS_SELF_TEST_FLAG_ALL))
			return 0;

		FALLTHROUGH;
	case GNUTLS_PK_MLKEM1024:
		ret = test_ml_kem_kat(GNUTLS_PK_MLKEM1024,
				      mlkem1024_dk, sizeof(mlkem1024_dk),
				      mlkem1024_ct, sizeof(mlkem1024_ct),
				      mlkem1024_ss, sizeof(mlkem1024_ss));
		if (ret < 0) {
			gnutls_assert();
			goto cleanup;
		}

		if (!(flags & GNUTLS_SELF_TEST_FLAG_ALL))
			return 0;

#endif /* HAVE_LEANCRYPTO */
		break;
	default:
		return gnutls_assert_val(GNUTLS_E_NO_SELF_TEST);
	}

	ret = 0;

cleanup:
	return ret;
}
